// Guards the stack-name-derived table naming in template.yaml — the isolation contract for the
// dev/sandbox environment (#27). Production is the canonical `tldr-app` stack and its table name is
// PINNED in source to `tldr-comments` (renaming would REPLACE the live table with an empty one); it
// takes no environment parameter, so nothing passed at deploy time can repoint it. Any other stack
// gets its own stack-scoped table, so dev can't share prod's data store. Parsing CloudFormation
// intrinsic tags with a real YAML lib needs custom tag handling, so we assert against the template
// text directly — which doubles as a drift guard: change the !If form and the assertion fails.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const template = readFileSync(resolve(here, '../template.yaml'), 'utf8');

// Pull the prod stack name and the pinned prod table literal straight from the template so these
// assertions track the source rather than re-hardcoding the values.
function prodStackName() {
  const m = template.match(/IsProd:\s*!Equals \[!Ref AWS::StackName, (\S+)\]/);
  return m && m[1];
}
function prodTableLiteral() {
  const m = template.match(/TableName:\s*!If \[IsProd, (\S+),/);
  return m && m[1];
}

// Mirror the template's `!If [IsProd, <prod literal>, !Sub '${AWS::StackName}-comments']`. The
// structural assertion below is the drift guard that keeps this mirror honest.
function resolveTableName(stackName) {
  return stackName === prodStackName() ? prodTableLiteral() : `${stackName}-comments`;
}

test('production is pinned by stack name, not an external parameter', () => {
  assert.match(template, /IsProd:\s*!Equals \[!Ref AWS::StackName, tldr-app\]/);
  // No Environment parameter exists — prod's identity is codified, not chosen at invocation.
  assert.doesNotMatch(template, /\n  Environment:\n/);
  // The table name is not an overridable parameter either (the same-named Output is fine — it's a
  // parameter, i.e. a `Name:` immediately followed by `Type:`, that must not exist).
  assert.doesNotMatch(template, /CommentsTableName:\s*\n\s+Type:/);
});

test('the table name derives from the stack name (prod literal vs stack-scoped)', () => {
  assert.match(
    template,
    /TableName:\s*!If \[IsProd, tldr-comments, !Sub '\$\{AWS::StackName\}-comments'\]/,
  );
});

test('prod keeps the exact legacy table name, hard-coded (no replacing rename)', () => {
  assert.equal(prodStackName(), 'tldr-app');
  assert.equal(prodTableLiteral(), 'tldr-comments');
  assert.equal(resolveTableName('tldr-app'), 'tldr-comments');
});

test('dev and prod resolve to distinct physical tables (no shared data store)', () => {
  assert.equal(resolveTableName('tldr-app-dev'), 'tldr-app-dev-comments');
  assert.notEqual(resolveTableName('tldr-app-dev'), resolveTableName('tldr-app'));
});

test('an ad-hoc stack name also gets its own table, never prod’s', () => {
  assert.equal(resolveTableName('tldr-app-experiment'), 'tldr-app-experiment-comments');
  assert.notEqual(resolveTableName('tldr-app-experiment'), prodTableLiteral());
});

// CORS allows the client's X-Client-Version header (issue #29). The client attaches it to every
// request; a custom header makes even the public GET a non-simple request, so the browser preflights
// it and API Gateway must list it in AllowHeaders — drop this and reads/posts break in-browser only
// (never in a unit test), so this guard stands in for that missing platform feedback.
test('CORS allows the client version header (X-Client-Version)', () => {
  assert.match(template, /AllowHeaders:[\s\S]*?- x-client-version/);
});

// CORS AllowMethods must list every HTTP method the routes actually use. Requests hit API Gateway
// directly, so a preflight is answered by this CorsConfiguration — and
// a method missing here means the browser's preflight gets no Access-Control-Allow-Origin and the call
// fails with a CORS error IN A REAL BROWSER ONLY (never in a unit test). DELETE (the vote toggle-off,
// issue #22) is the one that regressed; guard the whole set so the next added method can't slip.
test('CORS AllowMethods covers every method the routes use (incl. DELETE for the vote toggle-off)', () => {

import { readdirSync, existsSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

// This module lives at <canon>/engine/pack_loader/; the packs it scans at <canon>/packs/.
const canonRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
const packsDir = join(canonRoot, 'packs');

// A repo's own packs live at <root>/.claudinite/local/packs/<name>/ — tracked
// project content, discovered and run by the same engine as the mounted canon
// packs, and sitting at the same uniform depth as the shared mount
// (.claudinite/*/packs/). This is the canonical subdir relative to a consumer's
// checkout root. The pre-2026-07 layout put them one level up at
// .claudinite/local_packs/; discovery scans BOTH roots until the rename has
// propagated fleet-wide (Phase 4 drops the legacy scan), so a repo that hasn't
// been git-mv'd yet still loads.
export const LOCAL_PACKS_SUBDIR = join('.claudinite', 'local', 'packs');
export const LEGACY_LOCAL_PACKS_SUBDIR = join('.claudinite', 'local_packs');
export const localPacksDir = (root) => join(resolve(root), LOCAL_PACKS_SUBDIR);
export const legacyLocalPacksDir = (root) => join(resolve(root), LEGACY_LOCAL_PACKS_SUBDIR);

// Where a consumer materializes the vendored canon (vendoring/DESIGN.md): the
// corpus mirrored at canon-relative paths under this subdir. Tracked files in
// the interim; the planned future is a git submodule mounted at this same path
// — which is why nothing consumer-owned (local_packs/ above) lives inside it.
export const SHARED_SUBDIR = join('.claudinite', 'shared');

// Load a directory of `<name>/pack.mjs` manifests, isolating each import so one
// broken manifest can't sink the rest (a consumer-authored local pack.mjs must
// never disable every other pack's prose/checks/skills). Each loaded pack is
// stamped with `dir` (its own directory — prose and bundled skills resolve off
// this, so a pack's files never have to sit under a single shared root) and
// `local` (whether it came from a consumer's local_packs). A pack's skills live
// in its own tree — `<pack>/skills/<skill>/` is the one bundled-skill shape,
// canon and local alike (#385: a skill rides exactly one pack; there is no
// separate skills collection to own or cross-declare). A bundled skill's
// checks.mjs is gathered onto `skillChecks` and run by the runner only when the
// pack is active.
// A pack's declared adoption questions, validated: `questions` (an optional
// manifest field any pack may carry) must be an array of { id, prompt, distill? }
// with non-empty string ids and prompts, ids unique within the pack. A malformed
// entry is reported and skipped — one bad question must not mute the pack's valid
// ones (the registry's fail-soft posture). This is generic manifest-shape
// validation, so it lives with pack loading (scanPackDir reports the errors as
// load faults); the interview machinery imports it to read the valid questions.
export function packQuestions(pack) {
  const questions = [];
  const errors = [];
  const src = pack.questions;
  if (src === undefined || src === null) return { questions, errors };
  if (!Array.isArray(src)) {
    errors.push({
      what: `the "${pack.id}" pack declares a non-array "questions"`,
      fix: 'make questions an array of { id, prompt } entries',
    });
    return { questions, errors };
  }
  const seen = new Set();
  for (const q of src) {
    if (q === null || typeof q !== 'object' || typeof q.id !== 'string' || !q.id
      || typeof q.prompt !== 'string' || !q.prompt) {
      errors.push({
        what: `the "${pack.id}" pack declares a malformed question ${JSON.stringify(q)}`,
        fix: 'give each question a non-empty string "id" and "prompt"',
      });
      continue;
    }
    if (seen.has(q.id)) {
      errors.push({
        what: `the "${pack.id}" pack declares question id "${q.id}" twice`,
        fix: 'question ids must be unique within the pack — rename one',
      });
      continue;
    }
    seen.add(q.id);
    questions.push(q);
  }
  return { questions, errors };
}

async function scanPackDir(dir, { local, subdir }, errors) {
  const out = [];
  if (!existsSync(dir)) return out;
  const label = subdir ?? (local ? LOCAL_PACKS_SUBDIR : 'packs');
  // A non-directory (or unreadable path) at a scan root is a fault to REPORT, not
  // a crash — the whole point of discovery being fail-soft is a diagnostic instead
